      "surfaceId": "login_form",
      "catalogId": "https://a2ui.org/specification/v0_9/catalogs/basic/catalog.json"
    }
  },
  {
    "updateComponents": {
      "surfaceId": "login_form",
      "components": [
        {
          "id": "root",
          "component": "a2-vertical",
          "children": ["title", "username_input", "password_input", "login_button"]
        },
        {
          "id": "title",
          "component": "a2-text",
          "content": "用户登录",
          "size": "large",
          "color": "#333333"
        },
        {
          "id": "username_input",
          "component": "a2-input",
          "placeholder": "请输入用户名",
          "path": "/login/username",
          "label": "用户名"
        },
        {
          "id": "password_input",
          "component": "a2-input",
          "placeholder": "请输入密码",
          "path": "/login/password",
          "label": "密码"
        },
        {
          "id": "login_button",
          "component": "a2-button",
          "label": "登录",
          "style": "primary",
          "action": {
            "name": "login-in",
            "context": {
              "username": "/login/username",
              "password": "/login/password"
            }
          }
        }
      ]
    }
  },
  {
    "updateDataModel": {
      "surfaceId": "login_form",
      "path": "/login",
      "value": {
        "username": "",
        "password": ""
      }
    }
  }
]
</a2ui>

